{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.vendor_sku_bad_review as WITH po_base AS ( SELECT CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' OR UPPER(TRIM(sku)) LIKE \'BP%\' THEN UPPER(TRIM(sku)) WHEN UPPER(TRIM(sku)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, from_party AS vendor_name, order_date, transfer_branch_code, total_qty FROM SNITCH_DB.MAPLEMONK.LOGIC_PURCHASE_ORDER WHERE UPPER(TRIM(sku_group)) NOT IN ( \'PJ07\',\'PJ05\',\'SB4\',\'PP BINS\',\'NSB2\', \'MPB4\',\'MPB7\',\'CBB001\',\'CBS001\', \'89092763660\',\'89092763661\',\'89092763681\',\'4MST2649-02\' ) AND UPPER(TRIM(sku_group)) NOT ILIKE \'NT00%\' ), vendor_map AS ( SELECT DISTINCT sku_group, vendor_name FROM po_base ), sku_orders AS ( SELECT sku_group, MIN(order_date) AS first_order_date, SUM(CASE WHEN transfer_branch_code != 32 THEN total_qty ELSE 0 END) AS total_ordered_qty FROM po_base GROUP BY 1 HAVING MIN(order_date) >= \'2025-01-01\' ), shopify AS ( SELECT sku_group, SUM(CASE WHEN review_category ILIKE \'bad_review\' THEN 1 ELSE 0 END) AS shopify_bad_reviews FROM ( SELECT CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' OR UPPER(TRIM(sku)) LIKE \'BP%\' THEN UPPER(TRIM(sku)) WHEN UPPER(TRIM(sku)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku)) END END AS sku_group, review_category FROM snitch_db.maplemonk.review_shopify ) rs GROUP BY 1 ), return_review AS ( SELECT sku_group, SUM( CASE WHEN return_reasons IN ( \'Wrong or defective product\', \'Defective Product\', \'Finishing is not good\', \'Received a poor-quality product\', \'Product quality issue\', \'Product was dirty & had stains\' ) THEN 1 ELSE 0 END ) AS return_bad_reviews, SUM(COALESCE(sales_qty-return_qty, 0)) AS total_qty_sold, SUM(COALESCE(return_qty, 0)) AS total_return_qty FROM ( SELECT CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' OR UPPER(TRIM(sku)) LIKE \'BP%\' THEN UPPER(TRIM(sku)) WHEN UPPER(TRIM(sku)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku)) END END AS sku_group, sales_qty, return_qty, return_reasons FROM snitch_db.maplemonk.return_fact_items ) rfi GROUP BY 1 ), sku_metrics AS ( SELECT so.sku_group, so.first_order_date, so.total_ordered_qty, COALESCE(s.shopify_bad_reviews, 0) AS shopify_bad_reviews, COALESCE(rr.return_bad_reviews, 0) AS return_bad_reviews, COALESCE(s.shopify_bad_reviews, 0) + COALESCE(rr.return_bad_reviews, 0) AS total_bad_reviews, COALESCE(rr.total_qty_sold, 0) AS total_qty_sold, COALESCE(rr.total_return_qty, 0) AS total_return_qty, ROUND( 100.0 * (COALESCE(s.shopify_bad_reviews, 0) + COALESCE(rr.return_bad_reviews, 0)) / NULLIF(COALESCE(rr.total_qty_sold, 0), 0), 2 ) AS bad_review_pct, ROUND( 100.0 * COALESCE(rr.total_qty_sold, 0) / NULLIF(COALESCE(so.total_ordered_qty, 0), 0), 2 ) AS sold_pct, ROUND( 100.0 * COALESCE(rr.total_return_qty, 0) / NULLIF(COALESCE(rr.total_qty_sold, 0), 0), 2 ) AS return_pct FROM sku_orders so LEFT JOIN shopify s ON so.sku_group = s.sku_group LEFT JOIN return_review rr ON so.sku_group = rr.sku_group ) SELECT distinct sm.sku_group, vm.vendor_name, sm.total_ordered_qty, sm.first_order_date, sm.shopify_bad_reviews, sm.return_bad_reviews, sm.total_bad_reviews, sm.total_qty_sold, sm.total_return_qty, sm.bad_review_pct, sm.sold_pct, sm.return_pct FROM sku_metrics sm LEFT JOIN vendor_map vm ON sm.sku_group = vm.sku_group ORDER BY sm.total_bad_reviews DESC, sm.total_qty_sold DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            